llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Molecule 1: in patients with solid tumours, a 2 mg oral tablet of trametinib had a least-squares mean absolute bioavailability of 72.3% (90% CI 50.0–104.6%) versus an i.v. microtracer, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Molecule 6: in healthy men, apalutamide 240 mg orally had an absolute oral bioavailability of approximately 1.0 versus intravenous infusion, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Molecule 9: in healthy adults, safinamide 50 mg immediate-release tablets had an absolute bioavailability of about 95% (90% CI 90–99%) versus IV, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved condition-matched absolute bioavailability records in humans are above 20%, with central estimates ranging from about 31% to approximately 100%; the high assay-transfer scores and direct absolute measurements support a high prediction.",
  "evidence_gaps": [
    "No affirmative threshold-relevant evidence for F < 20% was retrieved.",
    "Some records are not explicitly absolute or use unspecified conditions, but the strongest records are direct absolute human measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

